/**
 * [INPUT]: Depends on creem/models/components for the entity types and the
 *          webhook event payload types (generated by the official SDK 1.x, all
 *          fields camelCase)
 * [OUTPUT]: Exports the Creem entity aliases CreemCheckout / CreemCheckoutCreateParams /
 *           CreemOrder / CreemTransaction / CreemSubscription / CreemRefund /
 *           CreemRefundResponse / CreemDispute / CreemCustomer / CreemProduct,
 *           plus the webhook event union CreemWebhookEvent and CreemWebhookEventType
 * [POS]: Type facade of lib/creem — lib/billing/creem and the webhook route touch
 *        SDK types only through here, so an SDK upgrade that renames things
 *        changes this one file; amounts are always integer cents, date fields
 *        are already parsed into Date by the SDK, while transaction's
 *        periodStart/periodEnd/createdAt are still epoch numbers
 * [PROTOCOL]: Update this header on changes, then check CLAUDE.md
 */

import type {
  CheckoutEntity,
  CreateCheckoutRequest,
  CustomerEntity,
  DisputeEntity,
  OrderEntity,
  ProductEntity,
  RefundEntity,
  RefundResponseEntity,
  SubscriptionEntity,
  TransactionEntity,
  WebhookEventEntity,
  WebhookSubscriptionEntity,
} from 'creem/models/components';

export type CreemCheckout = CheckoutEntity;
export type CreemCheckoutCreateParams = CreateCheckoutRequest;
export type CreemOrder = OrderEntity;
export type CreemTransaction = TransactionEntity;
export type CreemRefund = RefundEntity;
export type CreemRefundResponse = RefundResponseEntity;
export type CreemDispute = DisputeEntity;
export type CreemCustomer = CustomerEntity;
export type CreemProduct = ProductEntity;

/**
 * The subscription returned by the API (product/customer may be just an id
 * string) and the one carried by webhooks (always inline objects) are
 * structurally compatible — the adapter handles this union uniformly.
 */
export type CreemSubscription = SubscriptionEntity | WebhookSubscriptionEntity;

/** Webhook event strictly parsed by the SDK after signature verification (discriminated by eventType). */
export type CreemWebhookEvent = WebhookEventEntity;
export type CreemWebhookEventType = WebhookEventEntity['eventType'];
